When you mark a method as const, you are making a promise to the compiler and the caller: “Calling this function will not change the visible state of the object.”class Renderer {
public:
    // This method promises not to alter the Renderer state
    int getDrawCalls() const { 
        return m_drawCalls; 
    }

    // This method explicitly changes state
    void reset() { 
        m_drawCalls = 0; 
    }

private:
    int m_drawCalls = 0;
};
